import{z as A,x as i,o as r,c as d,q as l,j as o,D as t,d as e,s as n,S as s,b as E}from"./chunks/framework.C8m1ZpeB.js";const b=JSON.parse('{"title":"健康劳动供给","description":"","frontmatter":{"title":"健康劳动供给","date":"2026-09-18T00:00:00.000Z","section":"econ"},"headers":[],"relativePath":"econ/hi-health-labor.md","filePath":"econ/hi-health-labor.md","lastUpdated":1791413859000}'),p={name:"econ/hi-health-labor.md"};function m(h,a,D,c,u,_){const B=i("Mermaid");return r(),d("div",null,[a[2]||(a[2]=l('<h1 id="健康劳动供给" tabindex="-1">健康劳动供给 <a class="header-anchor" href="#健康劳动供给" aria-label="Permalink to &quot;健康劳动供给&quot;">​</a></h1><div class="epigraph"><p>健康既是消费品也是投资品：人生下来带着一笔健康存量，它按折旧率损耗，也可以用医疗与自己的时间去投资。</p><footer>—— Grossman, On the Concept of Health Capital and the Demand for Health, JPE, 1972</footer></div><p><a href="/econ/hi-risk-selection">上一课</a>把签约前的类型与保险市场的选择写完。缺口换到人这一边：保单里的「损失状态」其实是健康存量的一次折旧，而这笔存量决定一个人能供给多少劳动。本课把健康当资本写进劳动供给，再看保险怎么改这些决策。它是健康市场单元的第一课，后两课默认读完本课。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>标准劳动供给把时间当同质的：工资 \\(w\\) 乘工时。Grossman 的修正是先把总时间切一刀：健康时间与生病时间。劳动收入是 \\(w\\) 乘<strong>健康</strong>的工时，健康冲击因此同时做两件事：工资率没变，可卖的工时塌了；医疗支出还往上加。健康于是有双重身份——进入效用（生病的直接负效用），进入预算（健康时间是劳动的原料）。缺口是：健康存量与劳动供给互为因果——健康决定工时，工作条件又反过来折旧健康——把两者当单向关系会系统性估错。</p><p><span class="marginnote">Grossman 的投资条件：健康资本的边际收益（更多健康时间带来的工资与效用）等于利息加折旧成本。年龄上升使折旧加快，同样的投资买到的健康更少——这是「健康随年龄先升后降」的机制版本，不是偏好的变化。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>把存量写成递推：\\(H_{t+1}=(1-\\delta)H_t+I_t\\)，投资 \\(I_t\\) 用医疗品 \\(m_t\\) 与自己的时间生产；时间约束里生病时间与工作时间之和固定。健康冲击是折旧率 \\(\\delta\\) 的跳升，它有两个下游：工时与参与下降（劳动边际），医疗需求上升（投资边际）。实证的对象是把两个下游分开估：健康冲击对参与、工时与退休年龄的弹性。读数会发现健康的分量比财富大：退休决策里健康冲击的解释力超过财富——French 对健康、财富与工资的分解是这条线的代表。</p><p><span class="marginnote">数字实例：设健康存量 \\(H=100\\)，正常折旧 \\(\\delta=2\\%\\)，一年损耗 2 单位。一场大病把 \\(\\delta\\) 跳到 10%：同样不投资，一年就折掉 10 单位——想稳住存量，投资得从 2 加到 10，医疗需求就是这样跳上去的。</span></p>',9)),(r(),o(s,null,{default:t(()=>[n(B,{id:"mermaid-25",class:"mermaid",graph:"flowchart%20TD%0A%20%20W%5B%22%E5%B7%A5%E8%B5%84%E7%8E%87%20w%20%E4%B8%8D%E5%8F%98%22%5D%20--%3E%20TS%5B%22%E7%94%9F%E7%97%85%E6%97%B6%E9%97%B4%E4%B8%8A%E5%8D%87%2C%20%E5%81%A5%E5%BA%B7%E5%B7%A5%E6%97%B6%E5%A1%8C%E7%BC%A9%22%5D%0A%20%20SH%5B%22%E5%81%A5%E5%BA%B7%E5%86%B2%E5%87%BB%20%3D%20%E6%8A%98%E6%97%A7%E7%8E%87%20%CE%B4%20%E8%B7%B3%E5%8D%87%22%5D%20--%3E%20TS%0A%20%20TS%20--%3E%20Y%5B%22%E5%8A%B3%E5%8A%A8%E6%94%B6%E5%85%A5%E4%B8%8B%E9%99%8D%22%5D%0A%20%20SH%20--%3E%20M%5B%22%E5%8C%BB%E7%96%97%E6%94%AF%E5%87%BA%E4%B8%8A%E5%8D%87%22%5D%0A%20%20Y%20--%3E%20B%5B%22%E9%A2%84%E7%AE%97%E4%B8%A4%E4%BE%A7%E8%A2%AB%E6%8C%A4%3A%20%E6%94%B6%E5%85%A5%E9%99%8D%20%2B%20%E6%94%AF%E5%87%BA%E5%8D%87%22%5D%0A%20%20M%20--%3E%20B%0A"})]),fallback:t(()=>[...a[0]||(a[0]=[e(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=E("p",null,"反过来，工作折旧健康：职业伤害与职业压力改变 \\(\\delta\\)。识别上这叫联立性，工具变量要用外生的健康冲击（如急性病发作），不能用自报健康的水平。",-1)),a[4]||(a[4]=E("h2",{id:"机制",tabindex:"-1"},[e("机制 "),E("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[5]||(a[5]=E("p",null,[e("保险从两条线进入这张图。第一条：医疗保险降低投资品 \\(m_t\\) 的价格，健康投资的需求沿第一课的楔子放大——同一部机器，对象换成健康资本。第二条：保险本身成为劳动市场的摩擦。雇主提供的团体保险不可携带，换工作即换保单，健康者不敢动——文献叫 job lock，Gruber–Madrian 用保单延续政策的变化识别出它对流动性的压抑。伤残保险是第三条：它对「健康时间塌了」的人给收入，替代率高则退出的门槛降低——与"),E("a",{href:"/econ/ui-moral-hazard"},"失业保险与道德风险"),e("同一权衡，只是冲击更大、筛选更难。")],-1)),a[6]||(a[6]=E("p",null,[E("span",{class:"marginnote"},"术语翻译：job lock（工作锁定）=保单把人拴在工位上。团体保险由雇主出，换工作就要换保单甚至断保；自己或家人带病的人因此不敢跳槽——不是不想动，是动不起。")],-1)),(r(),o(s,null,{default:t(()=>[n(B,{id:"mermaid-38",class:"mermaid",graph:"flowchart%20TD%0A%20%20H%5B%22%E5%81%A5%E5%BA%B7%E5%AD%98%E9%87%8F%22%5D%20--%3E%20TH%5B%22%E5%81%A5%E5%BA%B7%E6%97%B6%E9%97%B4%22%5D%0A%20%20TH%20--%3E%20L%5B%22%E5%8A%B3%E5%8A%A8%E4%BE%9B%E7%BB%99%EF%BC%9A%E5%B7%A5%E6%97%B6%E4%B8%8E%E5%8F%82%E4%B8%8E%22%5D%0A%20%20L%20--%3E%20Y%5B%22%E5%8A%B3%E5%8A%A8%E6%94%B6%E5%85%A5%22%5D%0A%20%20Y%20--%3E%20INV%5B%22%E6%8A%95%E8%B5%84%EF%BC%9A%E5%8C%BB%E7%96%97%E4%B8%8E%E8%87%AA%E8%BA%AB%E6%97%B6%E9%97%B4%22%5D%0A%20%20INV%20--%3E%20H%0A%20%20SHOCK%5B%22%E5%81%A5%E5%BA%B7%E5%86%B2%E5%87%BB%EF%BC%9A%E6%8A%98%E6%97%A7%E8%B7%B3%E5%8D%87%22%5D%20--%3E%20H%0A%20%20DI%5B%22%E4%BC%A4%E6%AE%8B%E4%BF%9D%E9%99%A9%E4%B8%8E%E9%9B%87%E4%B8%BB%E4%BF%9D%E9%99%A9%22%5D%20--%3E%20L%0A"})]),fallback:t(()=>[...a[1]||(a[1]=[e(" Loading... ",-1)])]),_:1})),a[7]||(a[7]=l('<h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不写药品定价（下一课），不进宏观的人力资本核算与卫生支出的总量决定。健康测量有坑：自报健康随参照系移动，行政数据更硬但仍不含轻度状态；把自报健康的回归直接读成弹性，量级不可信。健康不平等的形成也不展开——那要把本课的存量动态与收入分配接起来，是另一门课的规模。</p><p><span class="marginnote">常见误区：把健康当成单纯消费品，病了顶多「不舒服」。Grossman 说它同时是生产资料：健康时间是工资的原料，存量塌一块，工时和收入跟着塌——生病要按「医疗费＋收入损失」两笔账一起算。</span></p><p>后课默认：健康是折旧的资本存量，保险既补贴它的投资品、又是劳动配置的摩擦。下一课转产业侧，问新药怎么定价。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>健康存量决定健康时间，健康时间是劳动的原料：健康与劳动供给互为因果。</li><li>Grossman：健康是消费品兼投资品，投资条件是边际收益对利息加折旧。</li><li>保险的三条线：补贴医疗投资、制造 job lock、降低伤残退出的门槛。</li><li>识别用外生健康冲击，不信自报健康的水平。</li><li>出处：Grossman, <em>JPE</em> 1972；Gruber–Madrian, <em>ILR Review</em> 1994；French, <em>REStud</em> 2005。</li></ul>',6))])}const T=A(p,[["render",m]]);export{b as __pageData,T as default};
